class Solution:
    def sharedLetters(self, words: List[str]) -> List[str]:
        rest = [list(w) for w in words[1:]]
        out = []
        for ch in words[0]:
            if all(ch in letters for letters in rest):
                for letters in rest:
                    letters.remove(ch)
                out.append(ch)
        return out

