function sharedLetters(words: string[]): string[] {
  const common = new Array(26).fill(Infinity);
  for (const w of words) {
    const cnt = new Array(26).fill(0);
    for (const ch of w) cnt[ch.charCodeAt(0) - 97]++;
    for (let c = 0; c < 26; c++) common[c] = Math.min(common[c], cnt[c]);
  }
  const out: string[] = [];
  for (let c = 0; c < 26; c++) {
    for (let t = 0; t < common[c]; t++) out.push(String.fromCharCode(97 + c));
  }
  return out;
}

